import { createChart, removeChart, getECModel } from '@/test/ut/core/utHelper';

describe('bar bandWidth with inversed time axis', function () {
    const day = 24 * 3600 * 1000;
    const base = 1704067200000; // 2024-01-01T00:00:00.000Z

    function getResult(inverse: boolean) {
        const chart = createChart();
        chart.setOption({
            xAxis: {
                type: 'time',
                inverse: inverse
            },
            yAxis: {
                type: 'value'
            },
            series: [{
                type: 'bar',
                data: [
                    [base, 10],
                    [base + day, 20],
                    [base + 2 * day, 15],
                    [base + 3 * day, 25]
                ]
            }]
        });
        const model = getECModel(chart);
        const xAxis = (model.getComponent('xAxis', 0) as any).axis;
        const scaleExtent = xAxis.scale.getExtent().slice();
        const bandWidth = model.getSeriesByIndex(0).getData().getLayout('bandWidth');
        removeChart(chart);
        return { scaleExtent, bandWidth };
    }

    it('adjusts time axis scale extent for bar overflow the same as non-inversed axis', function () {
        const inversed = getResult(true);
        const normal = getResult(false);
        expect(inversed.scaleExtent[0]).toBeCloseTo(normal.scaleExtent[0], 6);
        expect(inversed.scaleExtent[1]).toBeCloseTo(normal.scaleExtent[1], 6);
    });

    it('calculates the same positive bandWidth as non-inversed axis', function () {
        const inversed = getResult(true);
        const normal = getResult(false);
        expect(inversed.bandWidth).toBeGreaterThan(0);
        expect(inversed.bandWidth).toBeCloseTo(normal.bandWidth, 6);
    });
});
